    "Starting inventory": "Kezdő készlet",
    "Your first interaction": "Az első interakciód",
    "Every map starts with the starting room. Create it with the button on the left.": "Minden térkép a kezdőteremmel indul. Hozd létre a bal oldali gombbal.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "Válassz egy lapkát a palettán, és tedd a táblára; az R billentyűvel forgathatod. Egyelőre tegyél le két különböző lapkát: a játék során kiveszik őket a dobozból és felépítik.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "A Hős gomb (H) adja meg kalandozóink kezdőmezőit. Jelölj ki 2–4 mezőt a kezdőteremben.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "Hogy a térkép apránként táruljon fel, létre kell hoznunk egy új termet. Akkor jelenik meg, amikor egy objektumot használnak, egy termet megnyitó kiváltó beprogramozásával. Próbáljuk ki: kattints az Objektum gombra (O), és válassz egy ajtót. Ezután adj hozzá egy „Terem megnyitása” kiváltót.",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "Létrehoztad az első interakciódat a környezettel. A játékban a hős kinyitja az ajtót, és felszabadítja a következő terem lapkáit. Most töltsük meg azt a termet: tegyél egy ládát egy terembe, és programozz be egy kiváltót, amely tárgyakat ad a játékosoknak (a többi gomb és kiváltó erre vár).",
    "📂 Import a save of the game (.sav)": "📂 A játék mentésének importálása (.sav)",
    "Clear all": "Összes törlése",
    "Search an item…": "Tárgy keresése…",
    "Only what the party has": "Csak ami a csapatnál van",
    "skills": "készség",
