    "Replace the starting inventory with the one of this save?": "Lecseréled a kezdő készletet ennek a mentésnek a készletére?",
    "Imported from the save": "Importálva a mentésből",
    "This file is not a save of the game.": "Ez a fájl nem a játék mentése.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "Veterán csapatnak: amit a kampány kezdetén már birtokol, korábbi csatákban szerezve. A csapat a kampány kezdetekor kapja meg. A tárgyak a Műhelyből jönnek (Tárgyak és Fegyverek fül), a készségek a Készségek fülről (vagy a játékból). A generált térképek tárgyhalmazai kihagyják a csapatnál már meglévő egyedi tárgyakat, és a játék sosem ad egy tárgyat kétszer.",
