    "Recalculate tier {n} from tier {n} with the game’s curve? Their current numbers are replaced.": "Újraszámolod a(z) {n}. fokozatot a(z) {n}. fokozatból a játék görbéjével? A jelenlegi számok lecserélődnek.",
    "Recalculate tiers {n}–{n} from tier {n} with the game’s curve? Their current numbers are replaced.": "Újraszámolod a(z) {n}–{n}. fokozatot a(z) {n}. fokozatból a játék görbéjével? A jelenlegi számok lecserélődnek.",
    "OK: first move all its triggers to another object (you click it), then delete.": "OK: előbb áthelyezed az összes kiváltóját egy másik objektumra (rákattintasz), aztán törlöd.",
    "Cancel: delete anyway; the room stays without an opener until another object gets an “{q}” trigger.": "Mégse: mindenképp törlöd; a terem nyitó nélkül marad, amíg egy másik objektum nem kap egy „{Q}” kiváltót.",
