    "Placeholders: {vilao} {lugar} {alvo} {n} {X} {limite} {desde}… In Portuguese, “de {vilao}” becomes “do …” by itself.": "Helyőrzők: {vilao} {lugar} {alvo} {n} {X} {limite} {desde}… Portugálul a „de {vilao}” magától „do …” alakra változik.",
    "Narrative": "Narratíva",
