    "Go back to the text of the file? Your changes to this element are lost.": "Visszatérsz a fájl szövegéhez? Az elemen végzett változtatásaid elvesznek.",
    "Delete this new element?": "Törlöd ezt az új elemet?",
    "This is not valid JSON": "Ez nem érvényes JSON",
    "The id cannot change here: duplicate the element instead.": "Az azonosító itt nem változtatható: inkább kettőzd meg az elemet.",
    "one-way links": "egyirányú kapcsolat",
