    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "a kézzel elhelyezett szörnyek 1–2, 3 és 4 hősre vonatkozó fokozatai, a játék szabálya szerint (mint az ⚖ Kiegyensúlyozás egy szörnyön).",
