    "to chain maps on the world map, with scenes, choices and rewards between them.": "a térképek összefűzéséhez a világtérképen, közöttük jelenetekkel, választásokkal és jutalmakkal.",
    "turn and tilt it with the panel on the board (or Q/E, W/S, right-drag). Esc or the {n}D button returns to the plan.": "forgasd és döntsd meg a táblán lévő panellel (vagy Q/E, W/S, jobb gombos húzás). Az Esc vagy a {n}D gomb visszavisz az alaprajzhoz.",
    "{n}D view": "{n}D nézet",
