    "{n}D view: drag moves the map; turn and tilt it with the panel on the board (or Q/E, W/S, right-drag). Esc or the {n}D button returns to the plan.": "{n}D nézet: húzással mozgatod a térképet; forgasd és döntsd meg a táblán lévő panellel (vagy Q/E, W/S, jobb gombos húzás). Az Esc vagy a {n}D gomb visszavisz az alaprajzhoz.",
    "Campaign started: this map is map {n}. The campaign screen links maps, waypoints and dialogues and places them on the world map.": "A kampány elindult: ez a térkép a(z) {n}. térkép. A kampány képernyője térképeket, útpontokat és párbeszédeket kapcsol össze, és elhelyezi őket a világtérképen.",
    "From level {n} up a staircase must stand on tiles: put it on tiles of level {n} (only on the floor, level {n}, may it go off the tiles).": "A(z) {n}. szinttől felfelé a lépcsőnek lapkákon kell állnia: tedd a(z) {n}. szint lapkáira (csak a padlón, a(z) {n}. szinten lóghat le a lapkákról).",
    "Quick save done (kept in this browser).": "Gyorsmentés kész (ebben a böngészőben tárolva).",
    "The item pool has no items: add items to it (Workshop → Items, or Map setup).": "A tárgyhalmazban nincsenek tárgyak: adj hozzá tárgyakat (Műhely → Tárgyak, vagy Térképbeállítások).",
    "Waypoint added. Place it on the World map tab.": "Útpont hozzáadva. Helyezd el a Világtérkép fülön.",
    "they stay hidden until the object is used.": "rejtve maradnak, amíg az objektumot nem használják.",
    "“{q}” opens room {n}. Lay its tiles": "„{Q}” megnyitja a(z) {n}. termet. Rakd le a lapkáit",
    "“{q}” opens room {n}. Lay its tiles; they stay hidden until the object is used.": "„{Q}” megnyitja a(z) {n}. termet. Rakd le a lapkáit; rejtve maradnak, amíg az objektumot nem használják.",
    "Answer {n} → end": "{n}. válasz → vége",
    "Answers": "Válaszok",
    ". The AppData folder is hidden: paste that path into the address bar of the folder picker.": ". Az AppData mappa rejtett: illeszd be ezt az útvonalat a mappaválasztó címsorába.",
    "Author": "Szerző",
    "Author (goes into every map and campaign file you export)": "Szerző (bekerül minden általad exportált térkép- és kampányfájlba)",
    "Brings back the hints of Rooms, the explanations shown the first time a tab opens and the warnings you chose not to see again. Reset all settings: tips and warnings, window positions and sizes, author, export folder and autosave. Your maps and campaigns stay.": "Visszahozza a Rooms tippjeit, a fülek első megnyitásakor mutatott magyarázatokat és azokat a figyelmeztetéseket, amelyeket nem akartál többé látni. Az összes beállítás visszaállítása: tippek és figyelmeztetések, ablakok helye és mérete, szerző, exportálási mappa és automatikus mentés. A térképeid és kampányaid megmaradnak.",
    "Choose folder…": "Mappa kiválasztása…",
    "Close": "Bezárás",
    "Copies the Bigorna\\Mapas path": "Kimásolja a Bigorna\\Mapas útvonalat",
    "Copies the Bigorna\\Mapas path; paste it in Explorer's address bar": "Kimásolja a Bigorna\\Mapas útvonalat; illeszd be az Intéző címsorába",
    "Copy Bigorna\\Mapas path": "A Bigorna\\Mapas útvonal másolása",
    "Export folder": "Exportálási mappa",
    "No folder chosen: exported files are downloaded, and the game (with the mod) brings them from Downloads into its maps list by itself. Choosing the folder is only needed for autosave and the list of files.": "Nincs kiválasztott mappa: az exportált fájlok letöltődnek, és a játék (a moddal) magától áthozza őket a Letöltések mappából a térképlistájába. A mappa kiválasztása csak az automatikus mentéshez és a fájllistához kell.",
    "Open a .bmap or .bcamp made with Bigorna Rooms (replaces the current work). Brings chosen rooms of another Bigorna map into this one, without replacing it. Quick save keeps a copy in this browser": "Bigorna Rooms-szal készült .bmap vagy .bcamp megnyitása (lecseréli a jelenlegi munkát). Egy másik Bigorna térkép kiválasztott termeit hozza be ebbe, anélkül hogy lecserélné. A gyorsmentés egy másolatot tárol ebben a böngészőben",
    "Open a .bmap or .bcamp made with Bigorna Rooms (replaces the current work). Brings chosen rooms of another Bigorna map into this one, without replacing it. Quick save keeps a copy in this browser; quick load brings it back.": "Bigorna Rooms-szal készült .bmap vagy .bcamp megnyitása (lecseréli a jelenlegi munkát). Egy másik Bigorna térkép kiválasztott termeit hozza be ebbe, anélkül hogy lecserélné. A gyorsmentés egy másolatot tárol ebben a böngészőben; a gyorsbetöltés visszahozza.",
    "Settings": "Beállítások",
    "The maps folder of Descent is": "A Descent térképmappája:",
    "Tips and settings": "Tippek és beállítások",
    "Other settings": "Egyéb beállítások",
    "Files in the folder…": "Fájlok a mappában…",
    "Files in the folder": "Fájlok a mappában",
    "Everything in the folder (maps, campaigns and their folders), with the option to delete": "Minden, ami a mappában van (térképek, kampányok és mappáik), törlési lehetőséggel",
    "‹ Back": "‹ Vissza",
    "Refresh": "Frissítés",
    "Delete what you no longer want in the folder: maps (.bmap), campaigns (.bcamp) and their folders. What is deleted here is gone for good.": "Töröld, amire már nincs szükséged a mappában: térképek (.bmap), kampányok (.bcamp) és mappáik. Ami itt törlődik, az végleg eltűnik.",
    "The browser did not allow reading the folder.": "A böngésző nem engedte a mappa olvasását.",
