    "Export anyway?": "Mégis exportálod?",
    "Act II": "II. rész",
    "Click a socket (dot) of an elevated tile of this room at level {n}: sockets sit between two squares on a straight edge, never at a corner. The pillar belongs to the tile: it moves and enters the game with it.": "Kattints ennek a teremnek egy {n}. szintű emelt lapkáján egy foglalatra (pontra): a foglalatok két négyzet között vannak egy egyenes szélen, sosem sarokban. Az oszlop a lapkához tartozik: vele mozog, és vele kerül a játékba.",
    "Click the spaces where the heroes start (starting room only, {n} to {n}).": "Kattints a mezőkre, ahol a hősök kezdenek (csak a kezdőteremben, {n}–{n}).",
    "Click what you want to remove.": "Kattints arra, amit el akarsz távolítani.",
    "Monsters": "Szörnyek",
    "Monsters placed in a room. In the starting room they are there from the start; in any other room they enter automatically when the room opens. Monsters that come later (in a room already open) use a “{q}” trigger.": "Egy terembe helyezett szörnyek. A kezdőteremben kezdettől ott vannak; bármely más teremben automatikusan belépnek, amikor a terem megnyílik. A később érkező szörnyek (egy már nyitott terembe) egy „{Q}” kiváltót használnak.",
    "Objects": "Objektumok",
    "Pick the level of the elevated tile on the ribbon and click one of its sockets (the dots: between two squares on a straight edge, never a corner). The pillar belongs to that tile and enters the game with it. Level {n} tiles take short, medium or tall pillars; level {n} medium or tall; level {n} tall.": "Válaszd ki a menüszalagon az emelt lapka szintjét, és kattints az egyik foglalatára (a pontok: két négyzet között egy egyenes szélen, sosem sarokban). Az oszlop ahhoz a lapkához tartozik, és vele kerül a játékba. A(z) {n}. szintű lapkák alacsony, közepes vagy magas oszlopot fogadnak; a(z) {n}. szintűek közepeset vagy magasat; a(z) {n}. szintűek magasat.",
    "Pillars": "Oszlopok",
    "Place one or more of these spaces in a room: when the room opens, the game fills them from the room’s spawn pool with its own rule (points from the number of heroes, the map’s tier range). All may enter, or just one strong monster.": "Helyezz el egy vagy több ilyen mezőt egy teremben: amikor a terem megnyílik, a játék a saját szabályával tölti fel őket a terem megjelenési halmazából (pontok a hősök számából, a térkép fokozattartománya). Beléphet mind, vagy csak egyetlen erős szörny.",
    "Rotation {n}° (R)": "Elforgatás {n}° (R)",
    "Rotation {n}° (R). Pillar (object): a column placed on a square like any object, with texts and triggers": "Elforgatás {n}° (R). Oszlop (objektum): egy négyzetre helyezett oszlop, mint bármely objektum, szövegekkel és kiváltókkal",
    "Rotation {n}° (R). Pillar (object): a column placed on a square like any object, with texts and triggers; it holds nothing up.": "Elforgatás {n}° (R). Oszlop (objektum): egy négyzetre helyezett oszlop, mint bármely objektum, szövegekkel és kiváltókkal; nem tart semmit.",
    "Same cards as embers (the other face)": "Ugyanazok a kártyák, mint a parázs (a másik oldal)",
    "Same cards as fetid water (the other face)": "Ugyanazok a kártyák, mint a bűzös víz (a másik oldal)",
    "Same cards as spikes (the other face)": "Ugyanazok a kártyák, mint a tüskék (a másik oldal)",
    "Same cards as water (the other face)": "Ugyanazok a kártyák, mint a víz (a másik oldal)",
    "Tile {n} is already in this room (side A or B)": "A(z) {n}. lapka már ebben a teremben van (A vagy B oldal)",
    "Tiles": "Lapkák",
    "Underlays (go under the tiles": "Alátétek (a lapkák alá kerülnek",
    "Underlays (go under the tiles; {n} double-sided cards: water / spikes and embers / fetid water share them)": "Alátétek (a lapkák alá kerülnek; {n} kétoldalas kártya: a víz / tüskék és a parázs / bűzös víz osztozik rajtuk)",
    "amber ones are in another room (reusing them removes the earlier room).": "a borostyánszínűek egy másik teremben vannak (újrahasználatuk eltávolítja a korábbi termet).",
    "back: embers": "hátoldal: parázs",
    "back: fetid water": "hátoldal: bűzös víz",
    "back: spikes": "hátoldal: tüskék",
    "back: water": "hátoldal: víz",
    "filter…": "szűrés…",
    "in any other room they enter automatically when the room opens. Monsters that come later (in a room already open) use a “{q}” trigger.": "bármely más teremben automatikusan belépnek, amikor a terem megnyílik. A később érkező szörnyek (egy már nyitott terembe) egy „{Q}” kiváltót használnak.",
    "it holds nothing up.": "nem tart semmit.",
    "level {n}": "{n}. szint",
    "level {n} (ribbon). Greyed tiles are already in this room": "{n}. szint (menüszalag). A szürke lapkák már ebben a teremben vannak",
    "level {n} (ribbon). Greyed tiles are already in this room; amber ones are in another room (reusing them removes the earlier room).": "{n}. szint (menüszalag). A szürke lapkák már ebben a teremben vannak; a borostyánszínűek egy másik teremben vannak (újrahasználatuk eltávolítja a korábbi termet).",
    "level {n} tall.": "a(z) {n}. szintűek magasat.",
