    "the game decides: how many, which and how strong": "a játék dönt: hányan, kik és milyen erősek",
    "{n} double-sided cards: water / spikes and embers / fetid water share them)": "{n} kétoldalas kártya: a víz / tüskék és a parázs / bűzös víz osztozik rajtuk)",
    "{n} hp": "{n} ÉP",
    "{n} in this room": "{n} ebben a teremben",
    "{n}/{n} cards used": "{n}/{n} kártya használva",
    "{n}/{n} in the box": "{n}/{n} a dobozban",
    "Hero space {n}": "{n}. hősmező",
    "Space {n}. Heroes start here ({n} to {n} spaces in the starting room).": "{n}. mező. A hősök itt kezdenek ({n}–{n} mező a kezdőteremben).",
    ", or brought by a trigger when something happens.": ", vagy amelyeket egy kiváltó hoz be, amikor valami történik.",
    "Checklist": "Ellenőrzőlista",
    "Click a piece to edit it": "Kattints egy darabra a szerkesztéséhez",
    "Click the spaces where the heroes start (starting room only, {n} to {n}). (H)": "Kattints a mezőkre, ahol a hősök kezdenek (csak a kezdőteremben, {n}–{n}). (H)",
    "Click what you want to remove. (D)": "Kattints arra, amit el akarsz távolítani. (D)",
    "Create the starting room": "A kezdőterem létrehozása",
    "Create the starting room.": "Hozd létre a kezdőtermet.",
    "Doors, chests, tokens… Any object can carry triggers and requirements. Staircases and bridges are floor: they may go off the tiles. (O)": "Ajtók, ládák, jelzők… Bármelyik objektum hordozhat kiváltókat és feltételeket. A lépcsők és a hidak padlónak számítanak: lelóghatnak a lapkákról. (O)",
    "Edit": "Szerkesztés",
    "Erase the rooms of this map (tiles, objects, monsters, hero spaces, triggers). The workshop, the map setup and the campaign stay. Asks first and offers to export.": "A térkép termeinek törlése (lapkák, objektumok, szörnyek, hősmezők, kiváltók). A műhely, a térképbeállítások és a kampány megmarad. Előbb rákérdez, és felajánlja az exportálást.",
    "Esc clears": "Esc: törlés",
    "Esc selects": "Esc: kijelölés",
    "Fit the map in view": "A térkép igazítása a nézethez",
    "Give each room its fight: monsters placed in it with": "Adj minden teremnek harcot: szörnyek, amelyeket ezzel helyezel el:",
    "Give the map a name first": "Előbb adj nevet a térképnek",
    "Give the map a name.": "Adj nevet a térképnek.",
    "Hints": "Tippek",
    "Level": "Szint",
    "Monsters placed in a room. In the starting room they are there from the start": "Egy terembe helyezett szörnyek. A kezdőteremben kezdettől ott vannak",
    "Monsters placed in a room. In the starting room they are there from the start; in any other room they enter automatically when the room opens. Monsters that come later (in a room already open) use a “{q}” trigger. (E)": "Egy terembe helyezett szörnyek. A kezdőteremben kezdettől ott vannak; bármely más teremben automatikusan belépnek, amikor a terem megnyílik. A később érkező szörnyek (egy már nyitott terembe) egy „{Q}” kiváltót használnak. (E)",
    "Name of the map": "A térkép neve",
    "No room yet": "Még nincs terem",
    "Paste the copied piece (Ctrl+V): click where it goes": "A másolt darab beillesztése (Ctrl+V): kattints oda, ahová kerül",
    "Pick a tile in the palette and click the board. R rotates. Each physical tile (side A or B) only once per room; same-level tiles cannot overlap. Underlays go under the tiles. (T)": "Válassz egy lapkát a palettán, és kattints a táblára. Az R forgat. Minden fizikai lapka (A vagy B oldal) teremenként csak egyszer; az azonos szintű lapkák nem fedhetik egymást. Az alátétek a lapkák alá kerülnek. (T)",
    "Pick the level of the elevated tile on the ribbon and click one of its sockets (the dots: between two squares on a straight edge, never a corner). The pillar belongs to that tile and enters the game with it. Level {n} tiles take short, medium or tall pillars": "Válaszd ki a menüszalagon az emelt lapka szintjét, és kattints az egyik foglalatára (a pontok: két négyzet között egy egyenes szélen, sosem sarokban). Az oszlop ahhoz a lapkához tartozik, és vele kerül a játékba. A(z) {n}. szintű lapkák alacsony, közepes vagy magas oszlopot fogadnak",
    "Pick the level of the elevated tile on the ribbon and click one of its sockets (the dots: between two squares on a straight edge, never a corner). The pillar belongs to that tile and enters the game with it. Level {n} tiles take short, medium or tall pillars; level {n} medium or tall; level {n} tall. (P)": "Válaszd ki a menüszalagon az emelt lapka szintjét, és kattints az egyik foglalatára (a pontok: két négyzet között egy egyenes szélen, sosem sarokban). Az oszlop ahhoz a lapkához tartozik, és vele kerül a játékba. A(z) {n}. szintű lapkák alacsony, közepes vagy magas oszlopot fogadnak; a(z) {n}. szintűek közepeset vagy magasat; a(z) {n}. szintűek magasat. (P)",
    "Place": "Elhelyezés",
    "Place an object (a door, a lever, a chest…) and give it the trigger “{q}” to open the next room: the board is revealed little by little, as the players explore.": "Helyezz el egy objektumot (ajtót, kart, ládát…), és add neki a „{Q}” kiváltót a következő terem megnyitásához: a tábla apránként tárul fel, ahogy a játékosok felfedezik.",
    "Rooms": "Termek",
    "Rotate the selection or the piece in hand (R)": "A kijelölés vagy a kézben lévő darab forgatása (R)",
    "Set the author in ⚙ Settings (it goes into the map file).": "A szerzőt a ⚙ Beállításokban add meg (bekerül a térképfájlba).",
    "Settings: export folder, author, open, import, quick save/load": "Beállítások: exportálási mappa, szerző, megnyitás, importálás, gyorsmentés/-betöltés",
    "Split your map into rooms.": "Oszd fel a térképedet termekre.",
    "The Workshop: monsters, NPCs, items, tiles, objects, heroes and weapons of this map": "A Műhely: a térkép szörnyei, NJK-i, tárgyai, lapkái, objektumai, hősei és fegyverei",
    "Turn the map in three dimensions to see the layers ({n}). Looking only: go back to the plan to edit.": "Forgasd a térképet három dimenzióban a rétegek megtekintéséhez ({n}). Csak nézelődés: a szerkesztéshez térj vissza az alaprajzhoz.",
    "View": "Nézet",
    "Zoom in (+)": "Nagyítás (+)",
    "Zoom out (−)": "Kicsinyítés (−)",
    "arrows nudge": "nyilak: finom mozgatás",
