    "level {n} medium or tall": "a(z) {n}. szintűek közepeset vagy magasat",
    "level {n} tall. (P)": "a(z) {n}. szintűek magasat. (P)",
    "marks the squares where the heroes start, in the starting room ({n} to {n} squares). The players put their figures there before the first room appears.": "megjelöli a négyzeteket, ahol a hősök kezdenek, a kezdőteremben ({n}–{n} négyzet). A játékosok oda teszik a figuráikat, mielőtt az első terem megjelenik.",
    "same-level tiles cannot overlap. Underlays go under the tiles. (T)": "az azonos szintű lapkák nem fedhetik egymást. Az alátétek a lapkák alá kerülnek. (T)",
    "to see the map in relief: elevated tiles, pillars, stairs and ladders.": "a térkép domborzatos megtekintéséhez: emelt lapkák, oszlopok, lépcsők és létrák.",
    "wheel zooms": "görgő: nagyítás",
