    "Balance: sets the tiers for {n}–{n}, {n} and {n} heroes by the game's points (room intensity ÷ {n} × heroes × {n} × progression, shared by the monsters placed in this room), each one above the other": "Kiegyensúlyozás: beállítja a fokozatokat {n}–{n}, {n} és {n} hősre a játék pontjai szerint (terem intenzitása ÷ {n} × hősök × {n} × előrehaladás, a teremben elhelyezett szörnyek között elosztva), mindegyiket az előző fölé",
    "Edit in the workshop": "Szerkesztés a műhelyben",
    "Like the game's bosses (Levirax: tier {n}, {n} or {n} for {n}, {n} or {n} heroes). The difficulty (Journey, Heroic, Warfare) still applies on top.": "Mint a játék főellenségei (Levirax: {n}., {n}. vagy {n}. fokozat {n}, {n} vagy {n} hősnél). A nehézség (Utazás, Hősies, Háborúzás) ezen felül is érvényes.",
    "Room intensity": "A terem intenzitása",
    "Tier": "Fokozat",
    "Tier by the number of heroes": "Fokozat a hősök száma szerint",
    "Triggers of this monster: they run every time it is defeated, after the game’s own effects (loot, objectives). Taking it off with “{q}” does not count.": "A szörny kiváltói: minden alkalommal lefutnak, amikor elpusztul, a játék saját hatásai után (zsákmány, célok). Ha egy „{Q}” veszi le, az nem számít.",
    "When defeated": "Amikor elpusztul",
