    "{n} heroes": "{n} hős",
    "{n}–{n} heroes": "{n}–{n} hős",
    "⚖ Balance": "⚖ Kiegyensúlyozás",
    "Clear the map?": "Törlöd a térképet?",
    "Clear without exporting": "Törlés exportálás nélkül",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop, the other maps, the campaign and the author stay. Files already exported stay in the folder.": "Ez törli a(z) „{Q}” térkép {n} termét: lapkák, oszlopok, objektumok, szörnyek, hősmezők és kiváltóik, valamint a nevét és a térképbeállításait (szövegek, zene, küldetés, halmazok, számlálók). A műhely, a többi térkép, a kampány és a szerző megmarad. A már exportált fájlok a mappában maradnak.",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop and the author stay. Files already exported stay in the folder.": "Ez törli a(z) „{Q}” térkép {n} termét: lapkák, oszlopok, objektumok, szörnyek, hősmezők és kiváltóik, valamint a nevét és a térképbeállításait (szövegek, zene, küldetés, halmazok, számlálók). A műhely és a szerző megmarad. A már exportált fájlok a mappában maradnak.",
    "The map has nothing to clear.": "A térképen nincs mit törölni.",
    "Do you want to export it before clearing?": "Exportálod törlés előtt?",
    "Everything not exported is lost.": "Minden, ami nincs exportálva, elvész.",
    "Export, then clear": "Exportálás, majd törlés",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers. The workshop, the map setup (name, texts, music, pools), the other maps and the campaign stay. Files already exported stay in the folder.": "Ez törli a(z) „{Q}” térkép {n} termét: lapkák, oszlopok, objektumok, szörnyek, hősmezők és kiváltóik. A műhely, a térképbeállítások (név, szövegek, zene, halmazok), a többi térkép és a kampány megmarad. A már exportált fájlok a mappában maradnak.",
    "Writes the .bcamp and its maps (download), then clears.": "Kiírja a .bcamp fájlt és a térképeit (letöltés), aztán mindent töröl.",
