    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: short pillar, medium pillar, tall pillar.": "Még nincs: használd az Oszlop eszközt a foglalatain (${p.level}. szint a menüszalagon). Itt megengedett: alacsony oszlop, közepes oszlop, magas oszlop.",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: tall pillar.": "Még nincs: használd az Oszlop eszközt a foglalatain (${p.level}. szint a menüszalagon). Itt megengedett: magas oszlop.",
    "Pillars of this tile": "A lapka oszlopai",
