    "Music, scene, spawn pool, final mission, intro": "Zene, jelenet, megjelenési halmaz, végső küldetés, bevezető",
    "Name": "Név",
    "New rooms are born from an object: select it, add the trigger “{q}”. Pick a room here before touching what is in it.": "Az új termek egy objektumból születnek: jelöld ki, add hozzá a „{Q}” kiváltót. Válassz itt egy termet, mielőtt hozzányúlsz ahhoz, ami benne van.",
    "Room {n}: tile {n}B is elevated (level {n}) with no pillars.": "{n}. terem: a(z) {n}B lapka emelt ({n}. szint), de nincsenek oszlopai.",
