    "+ Another space": "+ Még egy mező",
    "Intensity of this room": "A terem intenzitása",
    "Tier range {n}–{n}, campaign progression {n} (": "Fokozattartomány: {n}–{n}, kampány-előrehaladás: {n} (",
    "What the game would do": "Mit tenne a játék",
    "When the group is defeated": "Amikor a csoport elpusztul",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Amikor a terem elindul, a játék a saját véletlen megjelenési szabályával tölti fel ezeket a mezőket: pontok = intenzitás ÷ {n} × hősök × {n} × előrehaladás; a térkép tartományának azt a legmagasabb fokozatát veszi, amelyet a pontok fedeznek (költségek: {n}, {n}, {n}, {n}, {n}, {n}…), és a halmaz azon szörnyei lépnek be, amelyeknek megvan ez a fokozat, mezőnként egy (legfeljebb {n}), amíg a pontok tartanak. A megmaradt pontok a következő kiegyensúlyozott terembe kerülnek. Beléphet mind, vagy csak egyetlen erős szörny.",
    "change": "módosítás",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "a térkép tartományának azt a legmagasabb fokozatát veszi, amelyet a pontok fedeznek (költségek: {n}, {n}, {n}, {n}, {n}, {n}…), és a halmaz azon szörnyei lépnek be, amelyeknek megvan ez a fokozat, mezőnként egy (legfeljebb {n}), amíg a pontok tartanak. A megmaradt pontok a következő kiegyensúlyozott terembe kerülnek. Beléphet mind, vagy csak egyetlen erős szörny.",
    "{n} (= spaces, default)": "{n} (= mezők, alapértelmezett)",
    "{n} balanced space in this room": "{n} kiegyensúlyozott mező ebben a teremben",
    "{n} hero": "{n} hős",
    "{n} monster, tier {n} (too few points: the minimum)": "{n} szörny, {n}. fokozat (túl kevés pont: a minimum)",
    "Opened by:": "Megnyitja:",
    "Remove this room": "A terem eltávolítása",
    "Text when revealed": "Szöveg felfedéskor",
    "Text after the room is set up": "Szöveg a terem felépítése után",
    "Text after the board is set up": "Szöveg a tábla felépítése után",
    "What the heroes find in it: a person, an object (the interaction tokens)": "Amit a hősök találnak benne: egy személy, egy objektum (az interakciós jelzők)",
    "Tile {n} is in another room: reusing it here needs that room removed first": "A(z) {n}. lapka egy másik teremben van: ahhoz, hogy itt újra használd, előbb el kell távolítani azt a termet",
    "give one an “{q}” trigger": "adj az egyiknek egy „{Q}” kiváltót",
    "no object opens this room; give one an “{q}” trigger": "egyetlen objektum sem nyitja meg ezt a termet; adj az egyiknek egy „{Q}” kiváltót",
    "no tiles; no object opens this room": "nincsenek lapkák; egyetlen objektum sem nyitja meg ezt a termet",
    "Go to that room": "Ugrás ahhoz a teremhez",
    "Open a room": "Terem megnyitása",
    "Opens": "Megnyitja",
    "a new room can be created here too.": "itt új terem is létrehozható.",
    "opened by “{q}”": "megnyitja: „{Q}”",
    "A scene (dialogue boxes)": "Egy jelenet (párbeszéddobozok)",
    "A scene of dialogue boxes (like the story flow), your own film full screen, a sound effect of the game or your own sound file. (a scene, a video, a sound)": "Párbeszéddobozokból álló jelenet (mint a történetfolyam), saját film teljes képernyőn, a játék egy hanghatása vagy saját hangfájl. (jelenet, videó, hang)",
    "A sound (game effect or your own file)": "Egy hang (játékbeli hatás vagy saját fájl)",
