    "Add or remove?": "Hozzáadás vagy eltávolítás?",
    "Add what?": "Mit adsz hozzá?",
    "Adds to (or removes from) the item pool or the monster spawn pool of the map, for the rest of the map. (item, monster spawn)": "Hozzáad a térkép tárgyhalmazához vagy szörnyek megjelenési halmazához (vagy elvesz belőle) a térkép hátralévő részére. (tárgy, szörnymegjelenés)",
    "Add…": "Hozzáadás…",
    "An object": "Egy objektum",
    "Cancel": "Mégse",
    "Change item / spawn pool": "Tárgy- / megjelenési halmaz módosítása",
    "Change which pool?": "Melyik halmazt módosítod?",
    "Monster spawn": "Szörnymegjelenés",
    "Play a scene, video or sound": "Jelenet, videó vagy hang lejátszása",
    "Play what?": "Mit játszol le?",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, spawn monsters, a tile, a room, an object, a monster)": "Játék közben felrak valamit a táblára, vagy levesz róla: lapkákat, objektumokat, szörnyeket, termeket. (lapka, objektum, szörnyek megjelenése, lapka, terem, objektum, szörny)",
    "Remove…": "Eltávolítás…",
    "Something appears on the board: a tile, an object or monsters. (a tile, an object, spawn monsters)": "Valami megjelenik a táblán: egy lapka, egy objektum vagy szörnyek. (lapka, objektum, szörnyek megjelenése)",
    "Takes something off the board: a tile, a room, an object or monsters. (a tile, a room, an object, a monster)": "Levesz valamit a tábláról: egy lapkát, egy termet, egy objektumot vagy szörnyeket. (lapka, terem, objektum, szörny)",
    "What happens when a hero uses this object. Several triggers run in order.": "Mi történik, amikor egy hős használja ezt az objektumot. Több kiváltó sorban fut le.",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "Játék közben felrak valamit a táblára, vagy levesz róla: lapkákat, objektumokat, szörnyeket, termeket. (lapka, objektum, lapka, terem, objektum, szörny)",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "Mi történik egyszer, amikor a számláló eléri a(z) {n} értéket (a számláló végösszegét). Több kiváltó sorban fut le.",
    "When the balanced group is defeated: “{q}”": "Amikor a kiegyensúlyozott csoport elpusztul: „{Q}”",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "Egy cél ezen a térképen, amelyet a szörny legyőzésekor jelentenek be, és a célok között szerepel. Egy cél nem fejezi be a térképet: azt a küldetés teszi (Térképbeállítások). Ott egy cél kiválasztható küldetésként.",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "A szörny legyőzésétől kezdve a körszámláló futtatja a benne lévő kiváltókat: N körönként (annyiszor, ahányszor megadod, vagy a térkép végéig), vagy egyszer, N körrel később. Hullámhoz tegyél bele egy „{Q}” kiváltót: a megjelenésnek saját „{Q}” kiváltója van.",
    "When this monster is defeated: “{q}”": "Amikor ez a szörny elpusztul: „{Q}”",
    "If the test fails: “{q}”": "Ha a próba sikertelen: „{Q}”",
    "After answer {n}: “{q}”": "A(z) {n}. válasz után: „{Q}”",
    "When the rounds come: “{q}”": "Amikor eljönnek a körök: „{Q}”",
