    "Heal, damage, apply or remove a condition on a spawn group, on the monsters of this room or on all. Heroes are healed at the table (use a text).": "Gyógyítás, sebzés, állapot alkalmazása vagy eltávolítása egy megjelenési csoporton, a terem szörnyein vagy mindenkin. A hősöket az asztalnál gyógyítják (használj szöveget).",
    "Remove conditions": "Állapotok eltávolítása",
