    "Take away": "Elvétel",
    "at least": "legalább",
    "gold": "arany",
    "The start of the map": "A térkép kezdete",
    "Use: when it reaches": "Használat: amikor eléri ezt:",
    "Watching from": "Figyelés kezdete:",
    "When the count reaches {n}": "Amikor a számláló eléri a(z) {n} értéket",
    "When this trigger runs": "Amikor ez a kiváltó lefut",
    "You found a": "Találtál egy ilyet:",
    "You lost a": "Elvesztettél egy ilyet:",
    "[count] is the name of the counter (highlighted like the rule words of the game), [n] the count after this trigger, [total] the total of the counter (Counts button). Missions and requirements can wait for the counter to reach a number (“{q}”).": "A [count] a számláló neve (kiemelve, mint a játék szabályszavai), az [n] a kiváltó utáni állás, a [total] a számláló végösszege (Számlálók gomb). A küldetések és feltételek várhatnak arra, hogy a számláló elérjen egy számot („{Q}”).",
    "count": "számláló",
    "of": "/",
