    "each answer may show a text afterwards and have its own triggers.": "minden válasz után megjelenhet egy szöveg, és mindegyiknek saját kiváltói lehetnek.",
    "\"{q}\": objective without its object": "„{Q}”: cél az objektuma nélkül",
    "A counter reaches a number": "Egy számláló elér egy számot",
    "An object is used (click it)": "Egy objektumot használnak (kattints rá)",
    "An objective does not end the map. To make it the mission, pick it in Map setup → Final mission → “{q}”.": "Egy cél nem fejezi be a térképet. Ha küldetéssé akarod tenni, válaszd ki itt: Térképbeállítások → Végső küldetés → „{Q}”.",
    "Completed when": "Teljesül, amikor",
    "Completed when it reaches": "Teljesül, amikor eléri ezt:",
    "Declared at the table": "Az asztalnál bejelentve",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”)": "Az asztalnál bejelentve: az alkalmazás csak a cél szövegét mutatja a célok között, és magától semmit sem ellenőriz. Akkor számít teljesítettnek, amikor az asztal megjelöli a játék Bigorna paneljén (F{n} → „{Q}”)",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”); only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "Az asztalnál bejelentve: az alkalmazás csak a cél szövegét mutatja a célok között, és magától semmit sem ellenőriz. Akkor számít teljesítettnek, amikor az asztal megjelöli a játék Bigorna paneljén (F{n} → „{Q}”); csak ekkor teljesül a(z) „{Q}” feltétel, és ha ezt választották küldetésnek, a térkép véget ér.",
    "Give each object that counts (each key, each lever) an “{q}” trigger with this counter. The mission ends by itself when the number is reached.": "Adj minden számító objektumnak (minden kulcsnak, minden karnak) egy „{Q}” kiváltót ezzel a számlálóval. A küldetés magától véget ér, amikor a számláló eléri a számot.",
    "Monsters are defeated": "Szörnyek elpusztulnak",
