    "What the players must do, as shown in the objectives": "Amit a játékosoknak meg kell tenniük, ahogy a célok között látszik",
    "only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "csak ekkor teljesül a(z) „{Q}” feltétel, és ha ezt választották küldetésnek, a térkép véget ér.",
