    "The shop opens in its own window over the board; the next triggers run when it closes. To charge an entrance or limit who may enter, put a requirement on this trigger.": "A bolt saját ablakban nyílik meg a tábla fölött; a következő kiváltók akkor futnak le, amikor bezárul. Ha belépődíjat kérnél, vagy korlátoznád, ki léphet be, tegyél feltételt erre a kiváltóra.",
    "The armory opens in its own window over the board; the next triggers run when it closes. Heroes whose weapons this map sets (Workshop) keep them.": "A fegyvertár saját ablakban nyílik meg a tábla fölött; a következő kiváltók akkor futnak le, amikor bezárul. Azok a hősök, akiknek a fegyvereit ez a térkép adja meg (Műhely), megtartják őket.",
