    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "A játék hat profilja (osztály, fegyverek, készségek és teljesítmények) bekerül a kampányba. Mindegyiket a játék hőse játssza (ahogy a játékban), vagy a névsorod egyik hőse, akit a hős saját lapján teszel be.",
