    "(the profile’s)": "(a profilé)",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "Minden fegyvernek egy hőse van a játékban (az alkatrészei, a bolt, a készlet és a teljesítmények követik). Ha egy másik hős fegyverét választod, cserébe ő kapja ezt. A számok a fegyverekből jönnek: a Fegyverek fülön módosíthatók. A fegyverek a profilhoz tartoznak: vele maradnak, ha a hős távozik.",
