    "Choose the type first: it decides the figure and the animated art in the app (the game has no others) and the behaviour rules of that family. Then the rest of the sheet opens.": "Előbb a típust válaszd ki: ez dönti el a figurát és az animált grafikát az alkalmazásban (a játéknak nincs más), valamint annak a családnak a viselkedési szabályait. Aztán megnyílik a lap többi része.",
