    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "Húzd a darabokat, hogy úgy állítsd össze a fegyvert, ahogy szeretnéd; a görgő (vagy a csúszka) a kiválasztott darab méretét változtatja, a Shift+görgő, a Q/E vagy a forgatócsúszka forgatja, a nyilak finoman mozgatják. Egy darab csak a saját dobozán belül látszik: ami kilóg belőle, le van vágva (halványan látszik).",
    "Drag the pieces to put the weapon together, forge the template and bake the pictures": "Húzd a darabokat a fegyver összeállításához, kovácsold ki a sablont, és égesd be a képeket",
