    "Portrait in the story boxes (speaker and cast). Transparent PNG of the bust, {n} px or more, looks best.": "Portré a történetdobozokban (beszélő és szereplők). A mellkép átlátszó PNG-ként, {n} px vagy nagyobb méretben mutat a legjobban.",
    "Potions and one-use cards the heroes spend during a quest. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Bájitalok és egyszer használatos kártyák, amelyeket a hősök egy küldetés során elhasználnak. Csak a műhelyben szereplő tárgyakat adhatják kiváltók, jutalmak és párbeszédek, csak ezeket ejthetik el szörnyek, és csak ezeket lehet legyártani.",
    "Preview": "Előnézet",
    "Price of the recipe (gold)": "A recept ára (arany)",
    "Put it in the round frame, like the game’s": "Kerek keretbe helyezés, mint a játékban",
    "Range": "Hatótávolság",
    "Rarity": "Ritkaság",
    "Recalculate the other tiers from this one with the game's own curve: health grows ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} per tier, defense +{n} per tier, attack +{n} up to tier {n} and then +{n} every two tiers. With this tier alone, it creates the tiers up to {n}": "A többi fokozat újraszámolása ebből a játék saját görbéjével: az életerő fokozatonként ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} szorzóval nő, a védekezés fokozatonként +{n}, a támadás +{n} a(z) {n}. fokozatig, utána két fokozatonként +{n}. Ha csak ez a fokozat van, létrehozza a fokozatokat a(z) {n}. fokozatig",
    "Recipe: (no item yet)": "Recept: (még nincs tárgy)",
