    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the map.": "A korai erős tárgyak könnyűvé teszik a harcokat; a túl kevés vagy gyenge tárgy lemaradásra ítéli a hősöket a szörnyekkel szemben. Válaszd ki őket tudatosan, a hősök térkép során való fejlődésére gondolva.",
