    "What the monster does on its turn, in order; “{q}” chains them. Speed, damage, aim, attack, range, healing, shield, initiative and range type are the numbers the app uses; the text is what the players read.": "Amit a szörny a fordulójában tesz, sorrendben; a „{Q}” láncolja őket. A sebesség, a sebzés, a célzás, a támadás, a hatótávolság, a gyógyítás, a pajzs, a kezdeményezés és a hatótávolság típusa az alkalmazás által használt számok; a szöveg az, amit a játékosok olvasnak.",
