    "With these weapons": "Ezekkel a fegyverekkel",
    "Worn by a hero: a card with its rule, kept in the party’s inventory. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Egy hős viseli: egy kártya a szabályával, a csapat készletében tartva. Csak a műhelyben szereplő tárgyakat adhatják kiváltók, jutalmak és párbeszédek, csak ezeket ejthetik el szörnyek, és csak ezeket lehet legyártani.",
    "Write plain text. The buttons put in the names the app fills in ([monster] = the name of this monster, [hero] = the name of the hero it targets (or another name the app fills in)) and the game icons. Rule words like scar, terrify or focus become the game’s highlighted terms by themselves.": "Írj egyszerű szöveget. A gombok beszúrják az alkalmazás által kitöltött neveket ([monster] = ennek a szörnynek a neve, [hero] = a célba vett hős neve (vagy egy másik, az alkalmazás által kitöltött név)) és a játék ikonjait. A szabályszavak, mint a megvág, megrémít vagy fókuszál, maguktól a játék kiemelt kifejezéseivé válnak.",
