    "the bell hangs in its frame: a bell on the table takes the bell frame, and with one frame only one bell hangs at a time": "a harang az állványában lóg: egy asztalon lévő harang elfoglalja a harangállványt, és egy állványon egyszerre csak egy harang lóghat",
