    "Erase the campaign, all its maps and its workshop from the editor": "A kampány, az összes térképe és a műhelye törlése a szerkesztőből",
    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "Minden térképnek, mellékküldetésnek és útpontnak itt van a helye és egy jelölőfajtája: fő küldetés, mellékküldetés, elbeszélő esemény vagy városlátogatás.",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "A kampányból minden törlődik a szerkesztőből, és ez nem vonható vissza:",
    "Export campaign": "Kampány exportálása",
    "Export, then delete": "Exportálás, majd törlés",
    "Files already exported stay in the folder": "A már exportált fájlok a mappában maradnak",
    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "A már exportált fájlok a mappában maradnak; ha akarod, ott töröld őket. Az automatikus mentés többé nem követi ezt a kampányt, így nem törli őket. A játék megőrzi minden olyan csapat előrehaladását, amely játszotta.",
    "Fit the whole flow in the view": "A teljes folyam igazítása a nézethez",
    "Give crafting materials": "Gyártási anyagok adása",
    "Give the campaign a name (campaign screen).": "Adj nevet a kampánynak (kampány képernyő).",
    "Happens as": "Így történik",
    "It waits for the next visit to the city after the card before it": "A város következő látogatására vár az előtte lévő kártya után",
    "Lay the cards out left to right": "A kártyák elrendezése balról jobbra",
    "Leads to": "Ide vezet",
