    "New variable (Spared the bandit, Sided with the rebels…)": "Új változó (Megkímélte a banditát, A lázadók mellé állt…)",
    "No remembered choice yet: in a question box, tick “{q}”.": "Még nincs megjegyzett választás: egy kérdésdobozban jelöld be ezt: „{Q}”.",
    "On the world map as": "A világtérképen így:",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG vagy JPG, {n}:{n} ({n}×{n} pontosan illik). Lefedi a játék által mutatott teljes keretet",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG vagy JPG, {n}:{n} ({n}×{n} pontosan illik). Lefedi a játék által mutatott teljes keretet; a játék vize, felperzselt földje, helynevei és útjai rejtve maradnak. A köd a játék saját térképének egy rögzített részét fedi (a Ködföldeket).",
    "Place this waypoint on the world map": "Az útpont elhelyezése a világtérképen",
    "Plays as": "Így fut le",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "Mutass egy vonalra, hogy kigyulladjon a nyila. Hogy lásd, hová vezet egy kártya, kattints a ● pontjára.",
