    "Stay and fill them": "Maradok és kitöltöm",
    "Story flow": "Történetfolyam",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "A választások, amelyekre a kampány egyik térképről a másikra emlékszik: megkímélte a banditát, a lázadók mellé állt, elvitte az átkozott gyűrűt… Egy választás akkor áll be, amikor a csapat egy „{Q}” jelölésű válasz mellett dönt (vagy egy „{Q}” akcióval), és a kampány hátralévő részében megmarad. A történetfolyam kártyái és a térképek kiváltói ezután csak akkor történhetnek meg, ha a csapat így döntött, vagy ha nem.",
    "The party moves on the world map (it goes after the selected card)": "A csapat mozog a világtérképen (a kijelölt kártya után kerül)",
    "The scene goes on with the next box when the film ends.": "A jelenet a következő dobozzal folytatódik, amikor a film véget ér.",
    "Then:": "Aztán:",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "Úgy exportálódnak, ahogy vannak. Töltsd ki őket, vagy töröld a feleslegeseket.",
    "Type the name of the campaign to confirm:": "A megerősítéshez írd be a kampány nevét:",
