    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "A térkép termeit építed. Válassz másik térképet, vagy adj hozzá térképeket, útpontokat és párbeszédeket a kampány képernyőjén („{Q}” fent).",
    "after Map {n}": "a(z) {n}. térkép után",
