    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "még semmi sem függ tőle: válaszd ki egy kártya „{Q}” mezőjében, vagy egy térképkiváltó „{Q}” feltételeként.",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "még semmi sem állítja be: jelöld be a „{Q}” négyzetet egy kérdésdobozban, és add neki ezt a nevet. Addig a(z) „{Q}” sosem igaz.",
    "only a question may branch": "csak egy kérdés ágazhat el",
