    "the scenes that follow it play in the same visit.": "az utána következő jelenetek ugyanabban a látogatásban futnak le.",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "a történetfolyam: {n} kártya, {n} jelenet a dobozaival, {n} történetváltozó",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "a műhely: {n} szörny, {n} NJK, {n} tárgy, {n} hős, {n} fegyver, {n} recept, {n} teljesítmény, {n} saját lapka/objektum",
