    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "{n} doboz: szöveg, kérdések és videók (saját filmek), egymás után lejátszva ugyanabban a keretben. A történet ezen pontján fut le: térkép után a térkép záró jelenete; útpont után megérkezéskor fut le; minden más előtt ez nyitja a kampányt.",
