    "Original maps": "Eredeti térképek",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "A játék eredeti térképeit a Bigorna mod a saját játékpéldányodból olvassa be: indítsd el egyszer a játékot a telepített moddal (a címképernyő előkészíti őket), aztán nyisd meg újra a szerkesztőt a játék Editor mappájából.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "A játék küldetései a szerkesztő térképeivé alakítva: lapkák, objektumok, termek, szörnyek és az a logika, amelyet a kiváltók ki tudnak fejezni.",
