    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "Ez mindent töröl, amit a szerkesztő tárol: a képernyőn lévő térképet vagy kampányt, a Műhelyt (szörnyek, tárgyak, anyagok, objektumok, importálva vagy készítve), a csomagokat (az alkalmazásban: a Pacotes mappát és benne minden csomagot), a szerkesztő által tárolt képeket, a gyorsmentést, az archetípusaidat, a tippeket és figyelmeztetéseket, az ablakok helyét és méretét, a szerzőt, az exportálási mappát és az automatikus mentést.",
